package io.forgeloop.control.application;
import io.forgeloop.control.domain.*; import jakarta.transaction.Transactional; import java.util.*; import org.springframework.stereotype.Service;
@Service public class FeatureRunService { private final FeatureRunRepository runs; private final DeliveryTaskRepository tasks; public FeatureRunService(FeatureRunRepository runs,DeliveryTaskRepository tasks){this.runs=runs;this.tasks=tasks;} @Transactional public FeatureRun submit(FeatureSubmission input){FeatureRun run=new FeatureRun(input.repository(),input.sourceRef(),input.title(),input.specification(),input.budgetUsd());run.addTask("PLANNER","Derive acceptance criteria and task DAG");run.addTask("BACKEND","Implement server-side changes");run.addTask("FRONTEND","Implement operator-facing changes");run.addTask("INDEPENDENT_TEST","Derive tests from source criteria");for(String gate:List.of("compile","unit-integration","graphql-contract","container-health","browser","security","spec-compliance"))run.addGate(gate);for(String criterion:input.specification().lines().filter(line->line.strip().startsWith("- ")).map(line->line.strip().substring(2)).toList())run.addCriterion(criterion);return runs.save(run);} @Transactional public DeliveryTask transitionTask(String taskId,TaskState state){DeliveryTask task=tasks.findById(taskId).orElseThrow(()->new IllegalArgumentException("Task not found"));task.transition(state);return task;} public FeatureRun get(String id){return runs.findById(id).orElseThrow(()->new IllegalArgumentException("Feature run not found"));} public List<FeatureRun> list(){return runs.findAll();} }
